package com.arenashowdown.lobby;

import com.arenashowdown.api.*;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.plugin.java.JavaPlugin;import org.jetbrains.annotations.NotNull;import java.util.*;

public final class ArenaLobbyPlugin extends JavaPlugin implements Listener,TabExecutor {
    private LobbyState state;private VisualManager visuals;private LobbyMenu menu;private boolean refreshWarning;
    @Override public void onEnable(){saveDefaultConfig();ArenaApi arena=getServer().getServicesManager().load(ArenaApi.class);OrchestrationApi orchestration=getServer().getServicesManager().load(OrchestrationApi.class);if(arena==null||orchestration==null){getLogger().severe("ArenaCore nao publicou as APIs necessarias");getServer().getPluginManager().disablePlugin(this);return;}if(!loadExistingWorld()){getLogger().severe("Mundo de lobby existente nao encontrado; nenhuma criacao automatica sera feita.");getServer().getPluginManager().disablePlugin(this);return;}state=new LobbyState(arena,orchestration);visuals=new VisualManager(this);menu=new LobbyMenu(this);getServer().getPluginManager().registerEvents(this,this);getServer().getPluginManager().registerEvents(menu,this);PluginCommand c=getCommand("lobby");c.setExecutor(this);c.setTabCompleter(this);Bukkit.getScheduler().runTask(this,visuals::rebuild);long period=Math.max(40,getConfig().getLong("refresh-seconds",5)*20);Bukkit.getScheduler().runTaskTimer(this,this::refresh,1,period);getLogger().info("ArenaLobby habilitado sem alterar blocos do mundo.");}
    private boolean loadExistingWorld(){String name=getConfig().getString("world","cassino_lobby_v2");if(Bukkit.getWorld(name)!=null)return true;java.io.File level=new java.io.File(new java.io.File(Bukkit.getWorldContainer(),name),"level.dat");return level.isFile()&&new WorldCreator(name).createWorld()!=null;}
    @Override public void onDisable(){if(visuals!=null)visuals.remove();for(Player p:Bukkit.getOnlinePlayers())if(isLobby(p.getWorld()))p.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());}
    void refresh(){state.refresh(championship(),getConfig().getInt("scoreboard.entries",5)).whenComplete((v,e)->{if(!isEnabled())return;Bukkit.getScheduler().runTask(this,()->{if(e!=null){if(!refreshWarning)getLogger().warning("Falha ao atualizar visuais (avisos repetidos serao suprimidos): "+root(e).getMessage());refreshWarning=true;return;}refreshWarning=false;visuals.update();for(Player p:Bukkit.getOnlinePlayers())if(isLobby(p.getWorld()))visuals.board(p);});});}
    LobbyState state(){return state;}String championship(){return getConfig().getString("championship","principal");}World world(){return Bukkit.getWorld(getConfig().getString("world","cassino_lobby_v2"));}boolean isLobby(World w){return w!=null&&w.getName().equals(getConfig().getString("world"));}
    Location location(String path){String name=getConfig().getString(path+".world",getConfig().getString("world"));World w=Bukkit.getWorld(name);return w==null||!getConfig().contains(path+".x")?null:new Location(w,getConfig().getDouble(path+".x"),getConfig().getDouble(path+".y"),getConfig().getDouble(path+".z"),(float)getConfig().getDouble(path+".yaw"),(float)getConfig().getDouble(path+".pitch"));}
    private void saveLocation(String path,Location l){getConfig().set(path+".world",l.getWorld().getName());getConfig().set(path+".x",l.getX());getConfig().set(path+".y",l.getY());getConfig().set(path+".z",l.getZ());getConfig().set(path+".yaw",l.getYaw());getConfig().set(path+".pitch",l.getPitch());saveConfig();}
    @EventHandler public void join(PlayerJoinEvent e){Bukkit.getScheduler().runTask(this,()->{if(isLobby(e.getPlayer().getWorld()))visuals.board(e.getPlayer());});}
    @EventHandler public void changed(PlayerChangedWorldEvent e){if(isLobby(e.getPlayer().getWorld()))visuals.board(e.getPlayer());else if(isLobby(e.getFrom()))e.getPlayer().setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());}
    @EventHandler public void interact(PlayerInteractEntityEvent e){if(!isLobby(e.getPlayer().getWorld())||!e.getRightClicked().getScoreboardTags().contains("arena_lobby_interaction"))return;e.setCancelled(true);String id=e.getRightClicked().getScoreboardTags().stream().filter(x->x.startsWith("arena_lobby_action_")).findFirst().orElse("").replace("arena_lobby_action_","");action(e.getPlayer(),id);}
    private void action(Player p,String action){switch(action){case "menu"->menu.open(p);case "ranking"->p.performCommand("arena ranking "+championship());case "status"->p.performCommand("arena status "+championship());case "admin"->{if(p.hasPermission("arena.lobby.admin"))menu.open(p);else p.sendMessage("§cSem permissao.");}default->p.sendMessage("§eInteracao sem acao configurada.");}}
    @EventHandler public void breaking(BlockBreakEvent e){if(protect(e.getPlayer(),"blocks"))e.setCancelled(true);}@EventHandler public void placing(BlockPlaceEvent e){if(protect(e.getPlayer(),"blocks"))e.setCancelled(true);}@EventHandler public void damage(EntityDamageEvent e){if(e.getEntity().getWorld()!=null&&isLobby(e.getEntity().getWorld())&&getConfig().getBoolean("protection.damage",true))e.setCancelled(true);}@EventHandler public void explode(EntityExplodeEvent e){if(isLobby(e.getLocation().getWorld()))e.blockList().clear();}@EventHandler public void ignite(BlockIgniteEvent e){if(isLobby(e.getBlock().getWorld())&&getConfig().getBoolean("protection.fire",true))e.setCancelled(true);}
    private boolean protect(Player p,String key){return isLobby(p.getWorld())&&getConfig().getBoolean("protection."+key,true)&&!(p.hasPermission("arena.lobby.admin")&&p.getGameMode()==GameMode.CREATIVE);}
    @Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String l,String @NotNull[] a){if(a.length==0){if(s instanceof Player p)menu.open(p);else help(s);return true;}try{switch(a[0].toLowerCase()){case "menu"->{if(s instanceof Player p)menu.open(p);}case "spawn"->{if(s instanceof Player p){Location at=location("spawn");if(at==null)p.sendMessage("§cSpawn ainda nao configurado.");else p.teleportAsync(at);}}case "setspawn"->{admin(s);Player p=player(s);saveLocation("spawn",p.getLocation());s.sendMessage("§aSpawn salvo.");}case "setchampionship"->{admin(s);need(a,2,"/lobby setchampionship <id>");getConfig().set("championship",a[1]);saveConfig();refresh();s.sendMessage("§aCampeonato exibido: "+a[1]);}case "hologram"->hologram(s,a);case "interaction"->interaction(s,a);case "reload"->{admin(s);reloadConfig();visuals.rebuild();refresh();s.sendMessage("§aArenaLobby recarregado.");}case "status"->s.sendMessage("§6ArenaLobby: §fworld="+(world()!=null)+", campeonato="+championship()+", ArenaParkour="+(Bukkit.getPluginManager().getPlugin("ArenaParkour")!=null));default->help(s);}}catch(Exception e){s.sendMessage("§c"+e.getMessage());}return true;}
    private void hologram(CommandSender s,String[]a){admin(s);Player p=player(s);need(a,3,"/lobby hologram <create|move|remove> <id> [ranking|championship|last]");String path="holograms."+a[2];switch(a[1].toLowerCase()){case "create"->{need(a,4,"/lobby hologram create <id> <tipo>");saveLocation(path,p.getLocation());getConfig().set(path+".type",a[3]);saveConfig();visuals.rebuild();}case "move"->{saveLocation(path,p.getLocation());visuals.rebuild();}case "remove"->{getConfig().set(path,null);saveConfig();visuals.rebuild();}default->throw new IllegalArgumentException("Acao de holograma invalida");}s.sendMessage("§aHologramas atualizados.");}
    private void interaction(CommandSender s,String[]a){admin(s);Player p=player(s);need(a,3,"/lobby interaction <create|remove> <id> [menu|ranking|status|admin]");String path="interactions."+a[2];String old=getConfig().getString(path+".uuid","");if(!old.isBlank()){Entity previous=Bukkit.getEntity(UUID.fromString(old));if(previous!=null)previous.remove();}if(a[1].equalsIgnoreCase("remove")){getConfig().set(path,null);saveConfig();s.sendMessage("§aInteracao removida.");return;}need(a,4,"/lobby interaction create <id> <acao>");Interaction entity=p.getWorld().spawn(p.getLocation(),Interaction.class,x->{x.setInteractionWidth(1.2f);x.setInteractionHeight(2f);x.setResponsive(true);x.addScoreboardTag("arena_lobby_interaction");x.addScoreboardTag("arena_lobby_action_"+a[3]);x.setPersistent(true);});getConfig().set(path+".uuid",entity.getUniqueId().toString());getConfig().set(path+".action",a[3]);saveConfig();s.sendMessage("§aInteracao criada: "+a[2]);}
    private void admin(CommandSender s){if(!s.hasPermission("arena.lobby.admin"))throw new IllegalArgumentException("Sem permissao: arena.lobby.admin");}private Player player(CommandSender s){if(!(s instanceof Player p))throw new IllegalArgumentException("Comando exclusivo para jogador.");return p;}private void need(String[]a,int n,String u){if(a.length<n)throw new IllegalArgumentException("Uso: "+u);}private void help(CommandSender s){s.sendMessage("§6/lobby §f<menu|spawn|setspawn|setchampionship|hologram|interaction|reload|status>");}private Throwable root(Throwable e){while(e.getCause()!=null)e=e.getCause();return e;}
    @Override public List<String> onTabComplete(@NotNull CommandSender s,@NotNull Command c,@NotNull String l,String @NotNull[]a){if(a.length==1)return List.of("menu","spawn","setspawn","setchampionship","hologram","interaction","reload","status").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();if(a.length==2&&a[0].equalsIgnoreCase("hologram"))return List.of("create","move","remove");if(a.length==2&&a[0].equalsIgnoreCase("interaction"))return List.of("create","remove");if(a.length==4&&a[0].equalsIgnoreCase("hologram")&&a[1].equalsIgnoreCase("create"))return List.of("ranking","championship","last");if(a.length==4&&a[0].equalsIgnoreCase("interaction")&&a[1].equalsIgnoreCase("create"))return List.of("menu","ranking","status","admin");return List.of();}
}
